import fixtures from './golden/prototype-decide.json';
import { minorUnits, type MinorUnits } from '../../money/types';
import { assess, assessPlan, prepareContext } from '../assess';
import { resolvePlan, resolvePlanStrict, withPrice } from '../plan';
import type { PurchaseCheck, Steadiness } from '../types';
import {
  dollarsToMinor,
  expectedUnderAmendments,
  toCheck,
  toSnapshot,
  type FixtureScenario,
} from './golden/adapter';

// D-22 parity against prototype-decide.json (generated by running the prototype's own code, 04-03).
// Differences allowed: 1 minor unit; named deliberate deviations live in deviations/*.test.ts.
const scenarios = fixtures.scenarios as unknown as FixtureScenario[];
const within = (a: number, b: number, tol = 1): void => {
  expect(Math.abs(a - b)).toBeLessThanOrEqual(tol);
};
const STEADINESS: Record<string, Steadiness> = { Steady: 'steady', Variable: 'variable', Volatile: 'volatile' };

function context(scn: FixtureScenario) {
  const r = prepareContext(toSnapshot(scn));
  if (!r.ok) throw new Error(`context for ${scn.name} did not resolve: ${r.reasons.join(',')}`);
  return r.context;
}

describe('fixture sanity', () => {
  it('has at least 18 scenarios with unique names', () => {
    expect(scenarios.length).toBeGreaterThanOrEqual(18);
    expect(new Set(scenarios.map((s) => s.name)).size).toBe(scenarios.length);
  });
});

describe('expectedUnderAmendments (D-33/D-35 transform)', () => {
  const base = scenarios.find((s) => s.name === 'loan-fits')!;
  const withProto = (over: Partial<FixtureScenario['prototype']['assess']>, extra: Partial<FixtureScenario> = {}) =>
    ({
      ...base,
      saving: 25_000,
      investing: 40_000,
      ...extra,
      prototype: { ...base.prototype, assess: { ...base.prototype.assess, ...over } },
    }) as FixtureScenario;

  it('a shortfall inside saving + investing is adjust with inv carrying the pause (D-35)', () => {
    const e = expectedUnderAmendments(withProto({ left: -250, w: [{ k: 'month', short: 250 }] }));
    expect(e).toEqual({ state: 'adjust', warnings: [{ code: 'inv', shortfall: 25_000 }] });
  });

  it('beyond the pausable amount the state is no and month carries the remainder (D-35)', () => {
    const e = expectedUnderAmendments(withProto({ left: -750 }));
    expect(e).toEqual({
      state: 'no',
      warnings: [
        { code: 'inv', shortfall: 65_000 },
        { code: 'month', shortfall: 10_000 },
      ],
    });
  });

  it('an inv from a floor above investing is dropped when nothing is short (D-35)', () => {
    const e = expectedUnderAmendments(withProto({ left: 10, w: [{ k: 'inv', short: 5 }] }));
    expect(e).toEqual({ state: 'fits', warnings: [] });
  });

  it('an invest check keeps month and cash only (D-33)', () => {
    const inv = withProto({ left: -100, w: [{ k: 'dsr', short: 3 }, { k: 'cash', short: 4 }] }, {
      check: { kind: 'invest', amount: 1, payment: { method: 'lump' } },
    });
    const e = expectedUnderAmendments(inv);
    expect(e.warnings).toEqual([
      { code: 'month', shortfall: 10_000 },
      { code: 'cash', shortfall: 400 },
    ]);
    expect(e.state).toBe('no');
  });

  it('only changes scenarios that are a buy with left < 0, an invest check, or a floor above investing', () => {
    for (const scn of scenarios) {
      const raw = scn.prototype.assess;
      const e = expectedUnderAmendments(scn);
      const rawCodes = raw.w.map((w) => w.k);
      const changed =
        e.state !== raw.state ||
        e.warnings.length !== raw.w.length ||
        e.warnings.some((w, i) => w.code !== rawCodes[i]);
      if (!changed || scn.prototype.plan.miss) continue; // miss: the instalment-path deviation, no verdict compared
      const ok = scn.check.kind === 'invest' || raw.left < 0 || scn.limits.investingFloor > scn.investing;
      expect({ name: scn.name, ok }).toEqual({ name: scn.name, ok: true });
    }
  });
});

describe.each(scenarios)('prototype parity: $name', (scn) => {
  const proto = scn.prototype;

  it('money basis matches', () => {
    const { money } = context(scn);
    within(money.incomeAverage, dollarsToMinor(proto.money.avg));
    within(money.incomeWorst, dollarsToMinor(proto.money.worst));
    within(money.incomeBest, dollarsToMinor(proto.money.best));
    expect(money.steadiness).toBe(STEADINESS[proto.money.steady]);
    expect(money.basis).toBe(proto.money.basis === 'avg' ? 'average' : 'worst');
    within(money.incomeBasis, dollarsToMinor(proto.money.inBasis));
    within(money.spendingBasis, dollarsToMinor(proto.money.exp));
  });

  it('plan matches', () => {
    const result = resolvePlan(toCheck(scn));
    expect(result.status).toBe('resolved');
    if (result.status !== 'resolved') return;
    const plan = result.plan;
    const pp = proto.plan;
    within(plan.dayOne, dollarsToMinor(pp.day));
    within(plan.monthly, dollarsToMinor(pp.mo));
    expect(plan.months).toBe(pp.n);
    // instalment path: the prototype flags miss unconditionally (named in instalment-path.test.ts); financed not compared.
    if (!pp.miss) within(plan.financed, dollarsToMinor(pp.fin));
    // D-20: per-month rounding accumulates up to half a unit per payment.
    within(plan.interest ?? 0, dollarsToMinor(pp.interest), Math.ceil(pp.n / 2) + 1);
  });

  const verdictIt = proto.plan.miss ? it.skip : it;
  verdictIt('verdict and ledger figures match (state and warnings through the D-33/D-35 transform)', () => {
    const v = assess(toSnapshot(scn), toCheck(scn));
    if (v.state === 'missing') throw new Error(`unexpected missing verdict: ${v.reasons.join(',')}`);
    const expected = expectedUnderAmendments(scn);
    expect(v.state).toBe(expected.state);
    expect(v.warnings.map((w) => w.code)).toEqual(expected.warnings.map((w) => w.code));
    v.warnings.forEach((w, i) => within(w.shortfall, expected.warnings[i]!.shortfall));
    const a = proto.assess;
    within(v.left, dollarsToMinor(a.left));
    within(v.cashAfter, dollarsToMinor(a.cashAfter));
    within(v.unsecuredAfter, dollarsToMinor(a.unsecAfter));
    within(v.investingAtRisk, dollarsToMinor(a.investAtRisk));
    within(v.investingAfter, dollarsToMinor(a.investAfter));
    within(v.mineDayOne, dollarsToMinor(a.mineCash));
    within(v.mineMonthly, dollarsToMinor(a.minePay));
    within(v.newMonthly, dollarsToMinor(a.newMo));
  });

  // D-35: where the investing floor sits above investing the prototype's fits predicate differs, so bisection is skipped.
  const bisectIt = proto.bisect !== null && scn.limits.investingFloor <= scn.investing && !proto.plan.miss ? it : it.skip;
  bisectIt('largest affordable price is within the prototype float bracket', () => {
    const ctx = context(scn);
    const check: PurchaseCheck = toCheck(scn);
    const price = check.kind === 'buy' ? check.price : check.amount;
    const fits = (p: number): boolean => {
      const c = withPrice(check, minorUnits(p) as MinorUnits);
      return assessPlan(ctx, c, resolvePlanStrict(c)).state === 'fits';
    };
    let engine: number | null = null;
    if (fits(0)) {
      let lo = 0;
      let hi: number = price;
      while (lo < hi) {
        const mid = Math.ceil((lo + hi) / 2);
        if (fits(mid)) lo = mid;
        else hi = mid - 1;
      }
      engine = lo;
    }
    const best = proto.bisect!.best;
    if (best === null) {
      expect(engine).toBeNull();
      return;
    }
    expect(engine).not.toBeNull();
    // D-20: the engine rounds each monthly payment half-up to a minor unit, the prototype keeps floats. A payment off by
    // up to half a unit moves the price at which a payment-driven check flips by 0.5 / (monthly / price) units, so that
    // bound (zero when nothing is paid monthly) is added to the prototype's own 22-iteration bracket width.
    const atBoundary = withPrice(check, minorUnits(engine!) as MinorUnits);
    const monthly = resolvePlanStrict(atBoundary).monthly;
    const roundingBand = monthly > 0 ? Math.ceil((0.5 * price) / monthly) + 1 : 0;
    within(engine!, dollarsToMinor(best), Math.ceil(price / 2 ** 22) + 1 + roundingBand);
  });
});
